const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
function Show($u,$n){
  try {
    $r = Invoke-RestMethod -Uri $u -Headers $h -TimeoutSec 40
    foreach ($i in $r) { "$($i.number)|$($i.state)|$($i.comments)|$($i.title)" }
  } catch { "ERR $u : $($_.Exception.Message)" }
}
"##### our-free-model ISSUES (most commented)"
Show 'https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model/issues?state=all&sort=comments&direction=desc&per_page=30' 30
"##### our-free-model RECENT ISSUES"
Show 'https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model/issues?state=all&sort=created&direction=desc&per_page=25' 25
`;
const r = await tools.pwsh({ command: script, description: "Fetch plugin issues from GitHub", timeoutMs: 120000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 8000) : JSON.stringify(r).slice(0,500));
